use filmcraft_render::{image::Image,blend::{Blend,composite}};use serde_json::json;
fn image(rgba:&[u8])->Image{Image{w:6,h:4,px:rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect()}}
fn main(){let mut cases=vec![];let colors=[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]];for(name,mode)in[("normal",Blend::Normal),("multiply",Blend::Multiply),("screen",Blend::Screen),("overlay",Blend::Overlay),("darken",Blend::Darken),("lighten",Blend::Lighten),("difference",Blend::Difference),("addition",Blend::LinearDodge)]{for opacity in[0.,0.33333334,1.]{let rgba:Vec<u8>=(0..24).flat_map(|i|colors[i%5]).collect();let child:Vec<u8>=(0..24).flat_map(|i|colors[(i*3+2)%5]).collect();let mut out=image(&rgba);composite(&mut out,&image(&child),opacity,mode);cases.push(json!({"blend":name,"opacity":opacity,"rgba":rgba,"child":child,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
